/**
 * The theme's shape, checked. One set of tokens and one set of finishes in every theme, each finish
 * role stating the same fields in all of them, colours named by the theme's tokens rather than
 * written out, and nothing in either file left unread by the code.
 *
 * The theme data is three files deep: `packages/theme/theme.json` and `finishes.json` are what the
 * library ships, `themes/<name>/` holds the alternatives (generated by `scripts/theme/generate-*.ts`
 * for shadcn and solid glass) and `themes/default/` is a copy of the first two, for an app that
 * installs a theme by name. `docs/specs/theme-roles.md` writes the rules down; this file is where
 * they are enforced, so a theme cannot quietly grow a token, lose a slot, or keep a colour that
 * lives in no token.
 *
 *   bun scripts/theme-lint.ts
 *
 * Run by `bun run check`.
 */
import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";

import { colourFields, readColour } from "./theme/finish-colour";
import { checkMaterial } from "./theme/material";
import { parseColor } from "./theme/oklch";
import { specBlock, specParts, specRows } from "./theme/spec";
import { checkStyle } from "./theme/style";

const root = join(import.meta.dir, "..");
const read = (path: string) => readFileSync(join(root, path), "utf8");
const readJson = <T>(path: string): T => JSON.parse(read(path)) as T;

/** The theme data a theme carries: colours in light and dark, and the values both appearances share. */
interface ThemeFile {
  cssVars: {
    theme: Record<string, string>;
    light: Record<string, string>;
    dark: Record<string, string>;
  };
}

/** One surface of the material: its fill, the gradient over it, its shadow and its edge. */
interface Finish {
  backgroundColor?: string;
  backgroundImage?: string;
  boxShadow?: string;
  borderColor?: string;
  backdropFilter?: string;
  material?: unknown;
}

interface FinishesFile {
  press: { scale: number };
  light: Record<string, Finish>;
  dark: Record<string, Finish>;
}

/** The two appearances a theme states. */
const appearances = ["light", "dark"] as const;

/** The fields a finish's colour may be written in. `boxShadow` is ink — see the spec. */
/** A clear value: unset, `transparent`, or a gradient that is transparent at every stop. */
const clear = (value: string | undefined) =>
  value === undefined ||
  value === "transparent" ||
  (value.startsWith("linear-gradient(") &&
    value
      .slice(value.indexOf(",") + 1, -1)
      .split(",")
      .every((stop) => stop.trim().startsWith("transparent")));

/** Whether a finish paints a fill: its colour or its gradient shows. */
const paints = (finish: Finish) => !clear(finish.backgroundColor) || !clear(finish.backgroundImage);

/** The themes: the default one, and every folder under `themes/`. */
const themes = readdirSync(join(root, "packages/theme/themes"))
  .filter((name) => statSync(join(root, "packages/theme/themes", name)).isDirectory())
  .sort();

const spec = read("docs/specs/theme-roles.md");
/** What the spec names: the A and C layers, and every finish's row. */
const specPartsOf = specParts(spec);

const failures: string[] = [];
const fail = (message: string) => failures.push(message);

/** The colours a finish may still write out: theme, appearance and the literal itself. */
const pending = new Set(
  specRows(specBlock(spec, "pending")).map(
    ([theme, appearance, value]) => `${theme} ${appearance} ${value}`,
  ),
);

/** The pending rows a finish really writes: a row no theme writes any more has been decided. */
const written = new Set<string>();

/** What the library writes but does not read: finish roles and tokens, by name. */
const unread = new Set(
  [...specBlock(spec, "unread").matchAll(/`([A-Za-z0-9-]+)`/g)].map((match) => match[1]),
);

/** The shadcn slots NSH itself resolves (`references/nsh/crates/nsh-base/src/theme.rs`). */
function shadcnSlots(): string[] {
  const rust = read("references/nsh/crates/nsh-base/src/theme.rs");
  const start = rust.indexOf("theme! {");
  const end = rust.indexOf("\n}", start);
  if (start === -1 || end === -1) throw new Error("theme.rs states no `theme! {` block");
  return [...rust.slice(start, end).matchAll(/^\s*\w+ = "([A-Za-z0-9-]+)",$/gm)].map((m) => m[1]);
}

/** Every file under `dir`, by extension. */
function files(dir: string, extensions: string[]): string[] {
  return readdirSync(join(root, dir), { withFileTypes: true }).flatMap((entry) => {
    const path = `${dir}/${entry.name}`;
    if (entry.isDirectory()) return files(path, extensions);
    return extensions.some((extension) => entry.name.endsWith(extension)) ? [path] : [];
  });
}

/** The code that reads a theme: the components, the theme module, and the demos. */
const code = [
  ...files("packages/ui", [".ts", ".tsx"]),
  ...files("apps/website/demos", [".ts", ".tsx"]),
]
  .map((path) => read(path))
  .join("\n");

/** The theme module, where a token's name is written once and mapped to its role. */
const themeModule = read("packages/theme/theme.ts");

const escape = (text: string) => text.replace(/[\\.+*?^$()|[\]{}]/g, "\\$&");

/** Whether the code reads a token, through `token()`, a `var()`, a class, or the theme module's map. */
function readsToken(name: string): boolean {
  const literal = escape(name);
  return (
    [
      new RegExp(`token\\(\\s*["'\`]${literal}["'\`]`),
      new RegExp(`var\\(--${literal}\\)`),
      // A class naming the token as a custom property: `rounded-(--radius-control)`.
      new RegExp(`\\(--${literal}\\)`),
      new RegExp(
        `\\b(?:bg|text|border|ring|fill|stroke|outline|decoration|caret|accent|shadow|from|via|to|divide|placeholder)-${literal}(?![a-z0-9-])`,
      ),
    ].some((pattern) => pattern.test(code)) ||
    new RegExp(`["'\`]${literal}["'\`]`).test(themeModule)
  );
}

/** Whether the code reads a finish role, through `finish.<role>` or `finish["<role>"]`. */
function readsRole(role: string): boolean {
  const literal = escape(role);
  return [new RegExp(`finish[?.\\[]\\s*["'\`]?${literal}(?![a-z0-9-])`)].some((pattern) =>
    pattern.test(code),
  );
}

// 1. The default theme is the one under `themes/default/`, byte for byte — it is a copy, and a copy
// that drifts is two answers to the same question.
for (const name of ["theme.json", "finishes.json"]) {
  const shipped = read(`packages/theme/${name}`);
  const copy = read(`packages/theme/themes/default/${name}`);
  if (shipped !== copy)
    fail(
      `packages/theme/themes/default/${name} is not packages/theme/${name}: cp packages/theme/${name} over it`,
    );
}

// 2. Every theme states the same tokens, in light and dark, and every shadcn slot among them.
const slots = shadcnSlots();
if (slots.length !== 31) fail(`theme.rs states ${slots.length} shadcn slots, not 31`);

// The spec names the same slots: the docs site groups tokens by its A list, so a slot it leaves out
// would be drawn under the wrong layer.
for (const name of slots)
  if (!specPartsOf.slots.includes(name))
    fail(`docs/specs/theme-roles.md: the A layer states no \`${name}\`, a slot NSH resolves`);
for (const name of specPartsOf.slots)
  if (!slots.includes(name))
    fail(`docs/specs/theme-roles.md: the A layer states \`${name}\`, which is no slot of theme.rs`);

const tokensOf = new Map<string, ThemeFile>();
for (const theme of themes) {
  const path = `packages/theme/themes/${theme}/theme.json`;
  const file = readJson<ThemeFile>(path);
  tokensOf.set(theme, file);
  const light = new Set(Object.keys(file.cssVars.light));
  const dark = new Set(Object.keys(file.cssVars.dark));
  for (const name of light) if (!dark.has(name)) fail(`${path}: \`${name}\` is in light, not dark`);
  for (const name of dark) if (!light.has(name)) fail(`${path}: \`${name}\` is in dark, not light`);
  for (const name of slots)
    if (!light.has(name))
      fail(`${path}: light states no \`${name}\`, a slot NSH resolves (theme.rs)`);
  for (const name of slots)
    if (!dark.has(name))
      fail(`${path}: dark states no \`${name}\`, a slot NSH resolves (theme.rs)`);
}

const [first, ...rest] = themes;
const names = Object.keys(tokensOf.get(first)?.cssVars.light ?? {}).sort();
for (const theme of rest) {
  const path = `packages/theme/themes/${theme}/theme.json`;
  const other = new Set(Object.keys(tokensOf.get(theme)?.cssVars.light ?? {}));
  for (const name of names)
    if (!other.has(name)) fail(`${path}: no token \`${name}\`, which ${first} states`);
  for (const name of other)
    if (!names.includes(name)) fail(`${path}: token \`${name}\`, which ${first} does not state`);
}

// 3. Every theme states the same finish roles, each with the same fields in all of them: a finish
// has one shape, and a theme with no gradient states a gradient of one colour.
const defaultFinishes = readJson<FinishesFile>("packages/theme/finishes.json");
const defaultRoles = Object.keys(defaultFinishes.light).sort();

// The spec says what each finish draws and who reads it, and the docs site shows that row: the
// spec's list of finishes is the theme's.
for (const role of defaultRoles)
  if (!specPartsOf.finishes.some((finish) => finish.role === role))
    fail(`docs/specs/theme-roles.md: states no finish \`${role}\`, which finishes.json has`);
for (const { role } of specPartsOf.finishes)
  if (!defaultRoles.includes(role))
    fail(`docs/specs/theme-roles.md: states finish \`${role}\`, which finishes.json has not`);

// The C layer is `cssVars.theme`: the spec lists the same keys, and the docs site shows them as
// the group that does not change with the appearance.
const sharedKeys = Object.keys(tokensOf.get(first)?.cssVars.theme ?? {});
for (const name of sharedKeys)
  if (!specPartsOf.shared.includes(name))
    fail(`docs/specs/theme-roles.md: the C layer states no \`${name}\`, which cssVars.theme has`);
for (const name of specPartsOf.shared)
  if (!sharedKeys.includes(name))
    fail(`docs/specs/theme-roles.md: the C layer states \`${name}\`, which cssVars.theme has not`);

// The three radii are one: `radius-control` and `radius-card` are the base at 0.8× and 1.4×,
// rounded to whole points, so a theme cannot state a tier out of step with the radius it derives
// from.
const pxOf = (value: string | undefined, path: string, name: string): number | undefined => {
  const match = value?.match(/^(\d+(?:\.\d+)?)px$/);
  if (!match) {
    fail(`${path}: \`${name}\` is \`${value ?? "missing"}\`, not a px length`);
    return undefined;
  }
  return Number(match[1]);
};
for (const theme of themes) {
  const path = `packages/theme/themes/${theme}/theme.json`;
  const shared = tokensOf.get(theme)?.cssVars.theme ?? {};
  const base = pxOf(shared.radius, path, "radius");
  if (base === undefined) continue;
  for (const [name, factor] of [
    ["radius-control", 0.8],
    ["radius-card", 1.4],
  ] as const) {
    const value = pxOf(shared[name], path, name);
    const expected = Math.round(base * factor);
    if (value !== undefined && value !== expected)
      fail(
        `${path}: \`${name}\` is ${value}px, not round(${factor} × \`radius\` ${base}px) = ${expected}px`,
      );
  }
}

const shapeOf = new Map<string, string[]>();
for (const appearance of appearances)
  for (const [role, finish] of Object.entries(defaultFinishes[appearance]))
    shapeOf.set(`${role}.${appearance}`, Object.keys(finish).sort());

for (const theme of themes) {
  const path = `packages/theme/themes/${theme}/finishes.json`;
  const file = readJson<FinishesFile>(path);
  for (const appearance of appearances) {
    const roles = Object.keys(file[appearance]).sort();
    const wanted = Object.keys(defaultFinishes[appearance]).sort();
    for (const role of wanted)
      if (!roles.includes(role))
        fail(`${path}: ${appearance} states no finish \`${role}\`, which the default theme does`);
    for (const role of roles)
      if (!wanted.includes(role))
        fail(`${path}: ${appearance} states \`${role}\`, which the default theme does not`);
    for (const [role, finish] of Object.entries(file[appearance])) {
      const have = Object.keys(finish).sort();
      const want = shapeOf.get(`${role}.${appearance}`);
      if (want === undefined) continue;
      // `material` is judged with its values in rule 4: a finish that leaves it out is named there.
      for (const field of want)
        if (field !== "material" && !have.includes(field))
          fail(`${path}: ${role}.${field} is missing, and every finish states a ${field}`);
      for (const field of have)
        if (!want.includes(field))
          fail(`${path}: ${role}.${field} is not a field the default theme's \`${role}\` states`);
      // A flat theme repeats its colour in the gradient rather than clearing it: a finish that
      // paints a fill in the default theme paints one here too, and a clear one stays clear.
      const base = defaultFinishes[appearance][role];
      if (base !== undefined && paints(finish) !== paints(base))
        fail(
          paints(base)
            ? `${path}: ${role} paints no fill (backgroundColor and backgroundImage both clear), and the default theme's does`
            : `${path}: ${role} paints a fill, and the default theme's is clear`,
        );
    }
  }

  // 4. A finish's colours are the theme's tokens — or ink, or a colour the spec has not decided
  // yet. A `var()` names a token the theme really has.
  const theme_ = tokensOf.get(theme);
  const known = new Set([
    ...Object.keys(theme_?.cssVars.theme ?? {}),
    ...Object.keys(theme_?.cssVars.light ?? {}),
  ]);
  for (const appearance of appearances) {
    for (const [role, finish] of Object.entries(file[appearance])) {
      for (const field of colourFields) {
        const value = finish[field];
        if (value === undefined) continue;
        const verdict = readColour(value, known, pending, `${theme} ${appearance}`);
        for (const row of verdict.pending) written.add(row);
        for (const problem of verdict.problems)
          fail(
            problem.kind === "unknown-token"
              ? `${path}: ${role}.${field} names token \`${problem.name}\`, which ${theme} does not have`
              : `${path}: ${role}.${field} writes ${problem.literal}, which is no token of the theme, no ink, and not in the spec's pending table`,
          );
      }
      // The platform material: stated on every finish, from NSH's lists, its tint a token of the theme.
      for (const problem of checkMaterial(
        path,
        `${role}.${appearance}`,
        finish as Record<string, unknown>,
        known,
      ))
        fail(problem);
      for (const [, name] of (finish.boxShadow ?? "").matchAll(/var\(--([A-Za-z0-9-]+)\)/g))
        if (!known.has(name))
          fail(`${path}: ${role}.boxShadow names token \`${name}\`, which ${theme} does not have`);
    }
  }
}

// 4b. Every theme states the same style (type, shape, size, stroke, focus, state, motion, icon,
// indicator): the keys the default theme states, enums from their lists, and the corner roles that
// are `theme.json`'s radii the same numbers.
for (const theme of themes) {
  const path = `packages/theme/themes/${theme}/finishes.json`;
  const shared = tokensOf.get(theme)?.cssVars.theme ?? {};
  for (const problem of checkStyle(
    path,
    readJson<Record<string, unknown>>(path),
    defaultFinishes as unknown as Record<string, unknown>,
    shared,
  ))
    fail(problem);
}

// 5. Nothing in the files is written and never read: a token no component, demo or class reads, a
// finish role no component reads. The spec's list says which ones are meant to be left to the app.
const shared = new Set(Object.keys(tokensOf.get(first)?.cssVars.theme ?? {}));
const shadcn = new Set(slots);
for (const name of names)
  if (!shadcn.has(name) && !shared.has(name) && !readsToken(name) && !unread.has(name))
    fail(`packages/theme/theme.json: token \`${name}\` is read nowhere and not left to the app`);
for (const role of defaultRoles)
  if (!readsRole(role) && !unread.has(role))
    fail(
      `packages/theme/finishes.json: finish \`${role}\` is read nowhere and not left to the app`,
    );

// The values both appearances share are tokens too, read the same way: a radius through a `rounded-(--radius-…)` class, a
// font family through `mono()`. A `font-` token is a family, not a colour — NSH reads the first
// family of the list (`theme.rs`'s `font_family`), so `monospace` alone is its generic one.
const themeBlock = tokensOf.get(first)?.cssVars.theme ?? {};
const isColour = (value: string) => {
  try {
    parseColor(value);
    return true;
  } catch {
    return false;
  }
};
for (const [name, value] of Object.entries(themeBlock)) {
  if (!readsToken(name) && !unread.has(name))
    fail(`packages/theme/theme.json: token \`${name}\` is read nowhere and not left to the app`);
  if (name.startsWith("font-") && isColour(value))
    fail(
      `packages/theme/theme.json: \`${name}\` is ${value}, a colour; a font token names a family`,
    );
}

// 6. The spec's pending table holds only colours its themes still write: a row left behind would be
// a colour the table lets back in, and the number the spec says is still undecided would be wrong.
for (const entry of pending)
  if (!written.has(entry))
    fail(
      `docs/specs/theme-roles.md: the pending table lists ${entry}, which no theme writes any more`,
    );

// Report.
if (failures.length > 0) {
  for (const message of failures) console.error(`theme-lint: ${message}`);
  console.error(`theme-lint: ${failures.length} problem${failures.length === 1 ? "" : "s"}`);
  process.exit(1);
}

const count = new Map<string, number>();
for (const theme of themes) {
  const file = readJson<FinishesFile>(`packages/theme/themes/${theme}/finishes.json`);
  for (const appearance of appearances)
    for (const finish of Object.values(file[appearance]))
      for (const field of colourFields)
        count.set(
          theme,
          (count.get(theme) ?? 0) + (finish[field]?.match(/var\(--[A-Za-z0-9-]+\)/g)?.length ?? 0),
        );
}
console.log(
  `theme-lint: ${themes.length} themes × ${names.length} tokens, ${defaultRoles.length} finishes each — ok`,
);
for (const [theme, aliases] of count)
  console.log(`  ${theme}: ${aliases} colours named by a token`);
